{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-processor.ts","file_text":"import { createHash, randomUUID } from 'node:crypto';
import { Redis } from 'ioredis';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { config } from '../../../packages/config/src/index.js';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { logger } from '../../../packages/observability/src/logger.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';
import type { ErasureRequestRow } from './repository.js';
import { formatErasureRequest } from './service.js';

export async function recoverExpiredErasureLeases(): Promise<number> {
  const result = await pool.query(
    `UPDATE customers.erasure_requests
     SET status='pending', available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
         last_error=COALESCE(last_error, 'worker_lease_expired'), updated_at=now()
     WHERE status='processing' AND lease_expires_at < now()`,
  );
  return result.rowCount ?? 0;
}

export async function claimErasureRequest(workerId: string, leaseSeconds = 60): Promise<ErasureRequestRow | undefined> {
  const result = await pool.query<ErasureRequestRow>(
    `UPDATE customers.erasure_requests
     SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
         lease_expires_at=now()+($2 || ' seconds')::interval, last_error=NULL, updated_at=now()
     WHERE id=(
       SELECT id FROM customers.erasure_requests
       WHERE status='pending' AND available_at<=now()
       ORDER BY available_at, created_at
       FOR UPDATE SKIP LOCKED
       LIMIT 1
     )
     RETURNING *`,
    [workerId, leaseSeconds],
  );
  return result.rows[0];
}

export async function failErasureRequest(id: string, attempts: number, maxAttempts: number, errorCode: string): Promise<void> {
  const delay = boundedExponentialBackoffSeconds(attempts);
  await pool.query(
    `UPDATE customers.erasure_requests
     SET status='failed', available_at=now()+($2 || ' seconds')::interval,
         locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error=$3, updated_at=now()
     WHERE id=$1`,
    [id, delay, errorCode],
  );
}

export async function executeErasure(job: ErasureRequestRow): Promise<void> {
  const merchantId = job.merchant_id;
  const customerId = job.customer_id;
  await ensureBucket();

  // 1. Gather email addresses for potential Mailpit cleanup
  const customerData = await pool.query<{ email: string }>(
    `SELECT email FROM customers.customers WHERE merchant_id = $1 AND id = $2`,
    [merchantId, customerId],
  );
  const contactEmails = await pool.query<{ value: string }>(
    `SELECT value FROM customers.contacts WHERE merchant_id = $1 AND customer_id = $2 AND kind = 'email'`,
    [merchantId, customerId],
  );
  const deliveryEmails = await pool.query<{ destination: string }>(
    `SELECT DISTINCT destination FROM operations.email_deliveries WHERE merchant_id = $1 AND customer_id = $2`,
    [merchantId, customerId],
  );

  const emailsToClean = new Set<string>();
  if (customerData.rows[0]?.email) emailsToClean.add(customerData.rows[0].email);
  for (const row of contactEmails.rows) if (row.value) emailsToClean.add(row.value);
  for (const row of deliveryEmails.rows) {
    if (row.destination && row.destination !== 'deleted@deleted.invalid') emailsToClean.add(row.destination);
  }

  // 2. Redact invoice documents in MinIO and update manifests
  const invoices = await pool.query<{ id: string; object_key: string | null }>(
    `SELECT id, object_key FROM payments.invoices WHERE merchant_id = $1 AND customer_id = $2`,
    [merchantId, customerId],
  );

  for (const inv of invoices.rows) {
    const objectKey = inv.object_key ?? `${merchantId}/invoices/${inv.id}.json`;
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) {
        chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
      }
      const content = Buffer.concat(chunks).toString('utf8');
      const doc = JSON.parse(content) as Record<string, unknown>;
      doc.customer = { id: customerId, deleted: true };
      const newBody = JSON.stringify(doc);
      await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), {
        'Content-Type': 'application/json',
      });
      const checksum = createHash('sha256').update(newBody).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests SET checksum = $1, metadata = metadata - 'customerEmail'
         WHERE merchant_id = $2 AND object_key = $3`,
        [checksum, merchantId, objectKey],
      );
    } catch (err: unknown) {
      const code = (err as { code?: string; name?: string })?.code ?? (err as { name?: string })?.name;
      if (code !== 'NoSuchKey' && code !== 'NotFound') {
        logger.warn({ err, objectKey }, 'failed to update invoice in minio');
      }
    }
  }

  // 3. Redact receipt documents in MinIO and update manifests
  const payments = await pool.query<{ id: string }>(
    `SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2`,
    [merchantId, customerId],
  );

  for (const payment of payments.rows) {
    const objectKey = `${merchantId}/receipts/${payment.id}.json`;
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) {
        chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
      }
      const content = Buffer.concat(chunks).toString('utf8');
      const doc = JSON.parse(content) as Record<string, unknown>;
      doc.customer = { id: customerId, deleted: true };
      const newBody = JSON.stringify(doc);
      await objectStore.putObject(DOCUMENT_BUCKET, objectKey, newBody, Buffer.byteLength(newBody), {
        'Content-Type': 'application/json',
      });
      const checksum = createHash('sha256').update(newBody).digest('hex');
      await pool.query(
        `UPDATE operations.document_manifests SET checksum = $1
         WHERE merchant_id = $2 AND object_key = $3`,
        [checksum, merchantId, objectKey],
      );
    } catch (err: unknown) {
      const code = (err as { code?: string; name?: string })?.code ?? (err as { name?: string })?.name;
      if (code !== 'NoSuchKey' && code !== 'NotFound') {
        logger.warn({ err, objectKey }, 'failed to update receipt in minio');
      }
    }
  }

  // 4. Delete customer import files in MinIO and cleanup manifests / customer_imports
  const imports = await pool.query<{ id: string; object_key: string }>(
    `SELECT id, object_key FROM customers.customer_imports WHERE merchant_id = $1`,
    [merchantId],
  );
  for (const imp of imports.rows) {
    try {
      const stream = await objectStore.getObject(DOCUMENT_BUCKET, imp.object_key);
      const chunks: Buffer[] = [];
      for await (const chunk of stream) chunks.push(typeof chunk === 'string' ? Buffer.from(chunk) : chunk);
      const content = Buffer.concat(chunks).toString('utf8');
      if (content.includes(customerId) || (customerData.rows[0]?.email && content.includes(customerData.rows[0].email))) {
        await objectStore.removeObject(DOCUMENT_BUCKET, imp.object_key).catch(() => {});
        await pool.query(`DELETE FROM operations.document_manifests WHERE merchant_id = $1 AND object_key = $2`, [merchantId, imp.object_key]);
        await pool.query(`DELETE FROM customers.customer_imports WHERE merchant_id = $1 AND id = $2`, [merchantId, imp.id]);
      }
    } catch {}
  }

  // 5. Delete any remaining non-financial manifests for this customer
  const manifests = await pool.query<{ object_key: string; document_type: string }>(
    `SELECT object_key, document_type FROM operations.document_manifests
     WHERE merchant_id = $1 AND customer_id = $2 AND document_type NOT IN ('invoice', 'receipt')`,
    [merchantId, customerId],
  );
  for (const manifest of manifests.rows) {
    await objectStore.removeObject(DOCUMENT_BUCKET, manifest.object_key).catch(() => {});
    await pool.query(`DELETE FROM operations.document_manifests WHERE merchant_id = $1 AND object_key = $2`, [merchantId, manifest.object_key]);
  }

  // 6. Delete Redis keys
  const redis = new Redis(config().REDIS_URL);
  try {
    await redis.del(`merchant:${merchantId}:customer:${customerId}`);
    await redis.del(`merchant:${merchantId}:customer:${customerId}:activity`);
    let cursor = '0';
    do {
      const [next, keys] = await redis.scan(cursor, 'MATCH', `merchant:${merchantId}:customer:${customerId}*`, 'COUNT', 100);
      cursor = next;
      if (keys.length > 0) {
        await redis.del(...keys);
      }
    } while (cursor !== '0');
  } catch (err) {
    logger.warn({ err }, 'failed to delete customer keys in redis');
  } finally {
    await redis.quit();
  }

  // 7. Delete OpenSearch document
  try {
    await searchClient.delete({
      index: CUSTOMER_INDEX,
      id: `${merchantId}:${customerId}`,
      refresh: true,
    });
  } catch (err: unknown) {
    const status = (err as { meta?: { statusCode?: number }; statusCode?: number })?.meta?.statusCode
      ?? (err as { statusCode?: number })?.statusCode;
    if (status !== 404) {
      logger.warn({ err }, 'failed to delete customer from opensearch');
    }
  }

  // 8. Clean Mailpit messages
  if (config().MAILPIT_API_URL && emailsToClean.size > 0) {
    for (const email of emailsToClean) {
      try {
        const searchRes = await fetch(`${config().MAILPIT_API_URL}/api/v1/search?query=to:${encodeURIComponent(email)}`);
        if (searchRes.ok) {
          const searchData = await searchRes.json() as { messages?: Array<{ ID: string }> };
          if (searchData.messages && searchData.messages.length > 0) {
            const ids = searchData.messages.map((m) => m.ID);
            await fetch(`${config().MAILPIT_API_URL}/api/v1/messages`, {
              method: 'DELETE',
              headers: { 'content-type': 'application/json' },
              body: JSON.stringify({ IDs: ids }),
            });
          }
        }
      } catch {}
    }
  }

  // 9. Atomic DB Cleanup
  await transaction(async (client) => {
    // A. Anonymize Invoices billing_snapshot
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot = jsonb_build_object('id', customer_id, 'deleted', true)
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // B. Anonymize Payments customer_snapshot & description
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot = jsonb_build_object('id', customer_id, 'deleted', true),
           description = CASE WHEN description IS NOT NULL THEN '[redacted]' ELSE NULL END,
           updated_at = now()
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // C. Redact Payment Attempts
    await client.query(
      `UPDATE payments.payment_attempts
       SET request_payload = jsonb_build_object('redacted', true),
           response_payload = CASE WHEN response_payload IS NOT NULL THEN jsonb_build_object('redacted', true) ELSE NULL END
       WHERE merchant_id = $1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       )`,
      [merchantId, customerId],
    );

    // D. Redact Refunds customer_email
    await client.query(
      `UPDATE payments.refunds
       SET customer_email = NULL
       WHERE merchant_id = $1 AND payment_intent_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       )`,
      [merchantId, customerId],
    );

    // E. Cancel and scrub Email Deliveries
    await client.query(
      `UPDATE operations.email_deliveries
       SET status = 'cancelled',
           cancelled_at = COALESCE(cancelled_at, now()),
           destination = 'deleted@deleted.invalid',
           subject = '[redacted]',
           text_body = '[redacted]',
           html_body = '[redacted]'
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // F. Delete Notification Preferences
    await client.query(
      `DELETE FROM operations.notification_preferences
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // G. Delete Notifications
    await client.query(
      `DELETE FROM operations.notifications
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // H. Delete Analytics Events
    await client.query(
      `DELETE FROM operations.analytics_events
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // I. Redact Audit Logs
    await client.query(
      `UPDATE platform.audit_logs
       SET metadata = jsonb_build_object('redacted', true)
       WHERE merchant_id = $1 AND target_type = 'customer' AND target_id = $2::text`,
      [merchantId, customerId],
    );

    // J. Cancel pending/retry background jobs for this customer
    await client.query(
      `UPDATE operations.jobs
       SET status = 'completed',
           payload = jsonb_build_object('redacted', true)
       WHERE merchant_id = $1 AND payload->>'customerId' = $2::text AND status IN ('pending', 'retry')`,
      [merchantId, customerId],
    );

    // K. Cancel pending outbox events for this customer
    await client.query(
      `UPDATE operations.outbox_events
       SET status = 'cancelled',
           payload = jsonb_build_object('redacted', true)
       WHERE merchant_id = $1 AND (aggregate_id = $2 OR payload->>'customerId' = $2::text) AND status <> 'published'`,
      [merchantId, customerId],
    );

    // L. Delete provider customer mappings
    await client.query(
      `DELETE FROM customers.provider_customer_mappings
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // M. Delete provider sandbox customers
    await client.query(
      `DELETE FROM provider_sandbox.customers
       WHERE merchant_id = $1 AND payflow_customer_id = $2`,
      [merchantId, customerId],
    );

    // N. Scrub provider sandbox payment intents
    await client.query(
      `UPDATE provider_sandbox.payment_intents
       SET provider_customer_id = NULL
       WHERE merchant_id = $1 AND payment_id IN (
         SELECT id FROM payments.payment_intents WHERE merchant_id = $1 AND customer_id = $2
       )`,
      [merchantId, customerId],
    );

    // O. Delete support messages and participants
    await client.query(
      `DELETE FROM customers.support_messages
       WHERE merchant_id = $1 AND author_type = 'customer' AND author_id = $2`,
      [merchantId, customerId],
    );
    await client.query(
      `DELETE FROM customers.support_participants
       WHERE customer_id = $1`,
      [customerId],
    );
    await client.query(
      `DELETE FROM customers.support_tickets
       WHERE merchant_id = $1 AND NOT EXISTS (
         SELECT 1 FROM customers.support_participants p WHERE p.ticket_id = customers.support_tickets.id
       )`,
      [merchantId],
    );

    // P. Delete payment method refs
    await client.query(
      `DELETE FROM customers.payment_method_refs
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // Q. Delete addresses
    await client.query(
      `DELETE FROM customers.addresses
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // R. Delete contacts
    await client.query(
      `DELETE FROM customers.contacts
       WHERE merchant_id = $1 AND customer_id = $2`,
      [merchantId, customerId],
    );

    // S. Delete customer record
    await client.query(
      `DELETE FROM customers.customers
       WHERE merchant_id = $1 AND id = $2`,
      [merchantId, customerId],
    );

    // T. Publish outbox event for customer erasure
    await addOutboxEvent(client, {
      eventType: EVENT_TYPES.CUSTOMER_ERASED,
      aggregateType: 'customer',
      aggregateId: customerId,
      merchantId,
      correlationId: randomUUID(),
      payload: { customerId, erasedAt: new Date().toISOString() },
    });

    // U. Mark erasure request completed
    const completed = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status = 'completed',
           completed_at = now(),
           updated_at = now(),
           locked_by = NULL,
           locked_at = NULL,
           lease_expires_at = NULL,
           last_error = NULL
       WHERE id = $1
       RETURNING *`,
      [job.id],
    );

    // V. Update idempotency response body
    if (completed.rows[0]) {
      await client.query(
        `UPDATE operations.idempotency_keys
         SET response_body = $2
         WHERE merchant_id = $1 AND scope = 'customer-erasure' AND request_hash = $3`,
        [merchantId, formatErasureRequest(completed.rows[0]), customerId],
      );
    }
  });
