/** Processes pending erasure requests with durable leases, crash recovery, and bounded retries. */
export async function startErasureProcessor(signal: AbortSignal): Promise<void> {
  const workerId = `customer-service-erasure-${randomUUID()}`;
  let lastLeaseRecovery = 0;

  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await recoverExpiredErasureLeases().catch((err) => logger.error({ err }, 'failed to recover erasure leases'));
      lastLeaseRecovery = Date.now();
    }

    const job = await claimErasureRequest(workerId).catch((err) => {
      logger.error({ err }, 'failed to claim erasure request');
      return undefined;
    });

    if (!job) {
      await new Promise((resolve) => setTimeout(resolve, 200));
      continue;
    }

    try {
      logger.info({ requestId: job.id, customerId: job.customer_id }, 'processing customer erasure request');
      await executeErasure(job);
      logger.info({ requestId: job.id, customerId: job.customer_id }, 'completed customer erasure request');
    } catch (error) {
      logger.error({ error, requestId: job.id, customerId: job.customer_id }, 'customer erasure request failed');
      await failErasureRequest(job.id, job.attempts, job.max_attempts, 'cleanup_failed').catch((err) => {
        logger.error({ err, requestId: job.id }, 'failed to update failed erasure status');
      });
    }
  }
}
"}

