  async createErasureRequest(merchantId: string, customerId: string, idempotencyKey: string): Promise<ReturnType<typeof formatErasureRequest>> {
    return await transaction(async (client) => {
      // 1. Check idempotency key in operations.idempotency_keys
      const existingKey = await client.query<{ request_hash: string; response_body: unknown }>(
        `SELECT request_hash, response_body FROM operations.idempotency_keys
         WHERE merchant_id = $1 AND scope = 'customer-erasure' AND key = $2`,
        [merchantId, idempotencyKey],
      );

      if (existingKey.rows[0]) {
        const storedHash = existingKey.rows[0].request_hash;
        if (storedHash !== customerId) {
          throw Object.assign(new Error('idempotency key reused for different customer'), { statusCode: 409 });
        }
        const existingReq = await this.repository.findErasureRequestByCustomer(client, merchantId, customerId);
        if (existingReq) {
          return formatErasureRequest(existingReq);
        }
      }

      // 2. Check if the customer already has an erasure request
      const existingReq = await this.repository.findErasureRequestByCustomer(client, merchantId, customerId);
      if (existingReq) {
        if (!existingKey.rows[0]) {
          await client.query(
            `INSERT INTO operations.idempotency_keys(merchant_id, scope, key, request_hash, response_status, response_body, expires_at)
             VALUES($1, 'customer-erasure', $2, $3, 202, $4, now() + interval '30 days')
             ON CONFLICT (merchant_id, scope, key) DO NOTHING`,
            [merchantId, idempotencyKey, customerId, formatErasureRequest(existingReq)],
          );
        }
        if (existingReq.status === 'failed') {
          const resetReq = await this.repository.resetFailedErasureRequest(client, merchantId, existingReq.id);
          if (resetReq) return formatErasureRequest(resetReq);
        }
        return formatErasureRequest(existingReq);
      }

      // 3. Customer does not have an erasure request yet. Check if customer exists in customers.customers
      const customer = await this.repository.findInTransaction(client, merchantId, customerId);
      if (!customer) {
        throw Object.assign(new Error('customer not found'), { statusCode: 404 });
      }

      // 4. Create new erasure request
      const newReq = await this.repository.createErasureRequest(client, merchantId, customerId);
      const formatted = formatErasureRequest(newReq);

      // 5. Record idempotency key
      await client.query(
        `INSERT INTO operations.idempotency_keys(merchant_id, scope, key, request_hash, response_status, response_body, expires_at)
         VALUES($1, 'customer-erasure', $2, $3, 202, $4, now() + interval '30 days')
         ON CONFLICT (merchant_id, scope, key) DO NOTHING`,
        [merchantId, idempotencyKey, customerId, formatted],
      );

      return formatted;
    });
  }

  async getErasureRequest(merchantId: string, requestId: string): Promise<ReturnType<typeof formatErasureRequest> | undefined> {
    const row = await this.repository.findErasureRequest(merchantId, requestId);
    return row ? formatErasureRequest(row) : undefined;
  }"}

