{"file_text":"import assert from 'node:assert/strict';
import test from 'node:test';
import { randomUUID } from 'node:crypto';
import { erasureRequestSchema } from '../packages/contracts/src/domain.js';
import { EVENT_TYPES, eventEnvelopeSchema } from '../packages/contracts/src/events.js';
import { formatErasureRequest } from '../apps/customer-service/src/service.js';

test('erasureRequestSchema validates valid erasure request records', () => {
  const valid = {
    id: randomUUID(),
    customerId: randomUUID(),
    status: 'pending',
    attempts: 0,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
    completedAt: null,
    lastError: null,
  };

  const parsed = erasureRequestSchema.parse(valid);
  assert.equal(parsed.id, valid.id);
  assert.equal(parsed.status, 'pending');
  assert.equal(parsed.attempts, 0);

  // Completed status with completedAt
  const completed = {
    ...valid,
    status: 'completed',
    attempts: 1,
    completedAt: new Date().toISOString(),
  };
  assert.equal(erasureRequestSchema.parse(completed).status, 'completed');

  // Failed status with lastError
  const failed = {
    ...valid,
    status: 'failed',
    attempts: 2,
    lastError: 'cleanup_failed',
  };
  assert.equal(erasureRequestSchema.parse(failed).lastError, 'cleanup_failed');

  // Invalid status rejected
  assert.throws(() => erasureRequestSchema.parse({ ...valid, status: 'unknown' }));
  // Negative attempts rejected
  assert.throws(() => erasureRequestSchema.parse({ ...valid, attempts: -1 }));
  // Invalid UUID rejected
  assert.throws(() => erasureRequestSchema.parse({ ...valid, customerId: 'not-a-uuid' }));
});

test('formatErasureRequest serializes database rows accurately', () => {
  const now = new Date();
  const id = randomUUID();
  const customerId = randomUUID();

  const formatted = formatErasureRequest({
    id,
    merchant_id: randomUUID(),
    customer_id: customerId,
    status: 'completed',
    attempts: 1,
    max_attempts: 8,
    available_at: now,
    locked_by: null,
    locked_at: null,
    lease_expires_at: null,
    last_error: null,
    created_at: now,
    updated_at: now,
    completed_at: now,
  });

  assert.deepEqual(formatted, {
    id,
    customerId,
    status: 'completed',
    attempts: 1,
    createdAt: now.toISOString(),
    updatedAt: now.toISOString(),
    completedAt: now.toISOString(),
    lastError: null,
  });
});

test('customer.erased event conforms to envelope contract', () => {
  const event = eventEnvelopeSchema.parse({
    eventId: randomUUID(),
    eventType: EVENT_TYPES.CUSTOMER_ERASED,
    eventVersion: 1,
    occurredAt: new Date().toISOString(),
    aggregateType: 'customer',
    aggregateId: randomUUID(),
    merchantId: randomUUID(),
    correlationId: randomUUID(),
    payload: {
      customerId: randomUUID(),
      erasedAt: new Date().toISOString(),
    },
  });

  assert.equal(event.eventType, 'customer.erased.v1');
});
