{"command":"create","path":"/workspace/source/scripts/test-erasure-integration.ts","file_text":"import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';

const gateway = process.env.GATEWAY_URL ?? 'http://localhost:3000';
const northstarKey = process.env.PAYFLOW_API_KEY ?? 'pf_local_dev_northstar_4ad1539de977';
const bluebirdKey = 'pf_local_dev_bluebird_924bd90d2201';

type ApiResponse<T> = { status: number; body: T };

async function api<T>(
  path: string,
  method = 'GET',
  body?: unknown,
  headers: Record<string, string> = {},
  apiKey = northstarKey,
): Promise<ApiResponse<T>> {
  const request: RequestInit = {
    method,
    headers: {
      authorization: `Bearer ${apiKey}`,
      ...headers,
      ...(body === undefined ? {} : { 'content-type': 'application/json' }),
    },
  };
  if (body !== undefined) request.body = JSON.stringify(body);
  const response = await fetch(`${gateway}${path}`, request);
  let payload: T;
  try {
    payload = await response.json() as T;
  } catch {
    payload = null as T;
  }
  return { status: response.status, body: payload };
}

async function sleep(ms: number) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

async function run() {
  console.log('--- Step 1: Authorization & Scopes Checks ---');
  // No auth header -> 401
  const unauthRes = await fetch(`${gateway}/v1/customers/${randomUUID()}/erasure-requests`, {
    method: 'POST',
    headers: { 'idempotency-key': 'test-key-12345678' },
  });
  assert.equal(unauthRes.status, 401, 'expected 401 for unauthenticated request');

  // Invalid key -> 401
  const invalidKeyRes = await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': 'test-key-12345678',
  }, 'invalid-key');
  assert.equal(invalidKeyRes.status, 401, 'expected 401 for invalid api key');

  console.log('--- Step 2: Idempotency-Key Header Validation ---');
  // Missing idempotency key -> 400
  const missingKeyRes = await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST');
  assert.equal(missingKeyRes.status, 400, 'expected 400 for missing idempotency key');

  // Short idempotency key (< 8 chars) -> 400
  const shortKeyRes = await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': 'short',
  });
  assert.equal(shortKeyRes.status, 400, 'expected 400 for short idempotency key');

  // Long idempotency key (> 200 chars) -> 400
  const longKeyRes = await api(`/v1/customers/${randomUUID()}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': 'x'.repeat(201),
  });
  assert.equal(longKeyRes.status, 400, 'expected 400 for long idempotency key');

  console.log('--- Step 3: Non-existent Customer & Cross-Tenant Access ---');
  const nonExistentCustomerId = randomUUID();
  const nonExistentRes = await api(`/v1/customers/${nonExistentCustomerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': `idem-${randomUUID()}`,
  });
  assert.equal(nonExistentRes.status, 404, 'expected 404 for non-existent customer');

  console.log('--- Step 4: Create Customer with Personal Data & Payments ---');
  const suffix = randomUUID();
  const customerEmail = `privacy-test-${suffix}@example.test`;
  const customerRes = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `ext-${suffix}`,
    email: customerEmail,
    name: 'Privacy Test Subject',
    phone: '+15551234567',
    metadata: { source: 'privacy-test' },
  });
  assert.equal(customerRes.status, 201);
  const customerId = customerRes.body.id;

  // Add contact
  await api(`/v1/customers/${customerId}/contacts`, 'POST', {
    kind: 'email',
    value: `alt-${suffix}@example.test`,
    isPrimary: false,
  });

  // Add address
  await api(`/v1/customers/${customerId}/addresses`, 'POST', {
    kind: 'billing',
    line1: '123 Privacy Lane',
    city: 'San Francisco',
    postalCode: '94105',
    country: 'US',
  });

  // Attach payment method
  const pmRes = await api<{ id: string }>(`/v1/customers/${customerId}/payment-methods`, 'POST', {
    providerToken: `tok_sandbox_success_${suffix}`,
    type: 'card',
    brand: 'visa',
    last4: '4242',
    billingName: 'Privacy Test Subject',
  });
  assert.equal(pmRes.status, 201);
  const paymentMethodId = pmRes.body.id;

  // Create payment
  const payRes = await api<{ id: string; status: string }>('/v1/payments', 'POST', {
    customerId,
    paymentMethodId,
    amount: 5000,
    currency: 'USD',
    description: 'Privacy test payment',
  }, { 'idempotency-key': `pay-${suffix}` });
  assert.equal(payRes.status, 202);
  const paymentId = payRes.body.id;

  // Wait for payment to succeed and receipt / projections to be processed
  console.log('Waiting for payment processing and projections...');
  await sleep(2000);

  // Cross-tenant check: Bluebird merchant cannot request erasure of Northstar customer
  const crossTenantRes = await api(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': `bluebird-idem-${suffix}`,
  }, bluebirdKey);
  assert.equal(crossTenantRes.status, 404, 'expected 404 when other merchant requests erasure');

  console.log('--- Step 5: Submit Erasure Request ---');
  const idemKey1 = `idem-key-1-${suffix}`;
  const erasureRes = await api<{
    id: string;
    customerId: string;
    status: string;
    attempts: number;
    createdAt: string;
    updatedAt: string;
    completedAt: string | null;
    lastError: string | null;
  }>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': idemKey1,
  });

  assert.equal(erasureRes.status, 202, 'expected 202 Accepted for valid erasure request');
  const erasureRequestId = erasureRes.body.id;
  assert.equal(erasureRes.body.customerId, customerId);
  assert.ok(['pending', 'processing', 'completed'].includes(erasureRes.body.status));
  assert.equal(typeof erasureRes.body.attempts, 'number');
  assert.ok(erasureRes.body.createdAt);
  assert.ok(erasureRes.body.updatedAt);

  console.log('--- Step 6: Idempotency & Replay Verification ---');
  // Reusing same key for same customer returns same erasure request
  const sameKeySameCustRes = await api<typeof erasureRes.body>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': idemKey1,
  });
  assert.equal(sameKeySameCustRes.status, 202);
  assert.equal(sameKeySameCustRes.body.id, erasureRequestId);

  // Different customer created to test key conflict
  const otherCustRes = await api<{ id: string }>('/v1/customers', 'POST', {
    externalReference: `other-${suffix}`,
    email: `other-${suffix}@example.test`,
    name: 'Other Customer',
  });
  const otherCustomerId = otherCustRes.body.id;

  // Reusing same key for DIFFERENT customer returns 409 Conflict
  const sameKeyDiffCustRes = await api(`/v1/customers/${otherCustomerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': idemKey1,
  });
  assert.equal(sameKeyDiffCustRes.status, 409, 'expected 409 Conflict for reused key with different customer');

  // New key for existing customer with erasure request returns existing erasure request
  const newKeyExistingCustRes = await api<typeof erasureRes.body>(`/v1/customers/${customerId}/erasure-requests`, 'POST', undefined, {
    'idempotency-key': `idem-key-2-${suffix}`,
  });
  assert.equal(newKeyExistingCustRes.status, 202);
  assert.equal(newKeyExistingCustRes.body.id, erasureRequestId);

  console.log('--- Step 7: Poll GET /v1/erasure-requests/:requestId for Completion ---');
  let finalStatus: typeof erasureRes.body | null = null;
  for (let i = 0; i < 40; i++) {
    const statusRes = await api<typeof erasureRes.body>(`/v1/erasure-requests/${erasureRequestId}`);
    assert.equal(statusRes.status, 200);
    assert.equal(statusRes.body.id, erasureRequestId);
    assert.equal(statusRes.body.customerId, customerId);

    if (statusRes.body.status === 'completed') {
      finalStatus = statusRes.body;
      break;
    }
    if (statusRes.body.status === 'failed') {
      throw new Error(`Erasure request failed: ${statusRes.body.lastError}`);
    }
    await sleep(250);
  }

  assert.ok(finalStatus, 'erasure request did not complete in time');
  assert.equal(finalStatus.status, 'completed');
  assert.ok(finalStatus.completedAt !== null);
  assert.equal(finalStatus.lastError, null);
  assert.ok(finalStatus.attempts >= 1);
  console.log('Erasure request completed successfully:', finalStatus);

  console.log('--- Step 8: Verify Customer Profile Is Deleted ---');
  // Customer GET should return 404
  const getCustomerRes = await api(`/v1/customers/${customerId}`);
  assert.equal(getCustomerRes.status, 404, 'expected customer to be 404 after erasure');

  // Customer subresources should return 404
  const getPmRes = await api(`/v1/customers/${customerId}/payment-methods/${paymentMethodId}`);
  assert.equal(getPmRes.status, 404, 'expected payment method to be 404 after erasure');

  console.log('--- Step 9: Verify Financial Records are Retained and Anonymized ---');
  const getPaymentRes = await api<{
    id: string;
    customerId: string;
    amount: number;
    currency: string;
    status: string;
    description: string | null;
  }>(`/v1/payments/${paymentId}`);
  assert.equal(getPaymentRes.status, 200, 'expected payment record to be retained');
  assert.equal(getPaymentRes.body.id, paymentId);
  assert.equal(getPaymentRes.body.amount, 5000);
  assert.equal(getPaymentRes.body.currency, 'USD');

  console.log('All end-to-end customer erasure assertions passed successfully!');
}

run().catch((err) => {
  console.error('Test failed:', err);
  process.exit(1);
});
"}

